void BfmeAptScreenMainMenu::_bfme_multiplayerButtonPressed( const char *name )
{
	(void)name;
	if ( m_firewall.m_checkFirewall08 && !m_firewall.applicationIsEnabled() )
	{
		{
			AsciiString message( "APT:FirewallPopUpMessage" );
			g_theWindowManager->bfme_setAptText( message,
				TheGameText->fetch( "GUI:FirewallPopUpMessage" ) );
		}
		{
			AsciiString title( "APT:FirewallPopUpTitle" );
			g_theWindowManager->bfme_setAptText( title,
				TheGameText->fetch( "GUI:FirewallPopUpTitle" ) );
		}
		g_theWindowManager->add( m_movie250, "FirewallMessageOpen", 0, 0,
			0, 0, 0, 0 );
	}
	else
	{
		g_theWindowManager->add( m_movie250, "StartMultiplayerNav", 0, 0,
			0, 0, 0, 0 );
	}
}
